pub fn bundle_identity(
    bundle: &std::path::Path,
) -> Result<capsule_identity::LabCid, capsule_identity::Refusal> {
    let read = |path: &str| capsule_identity::BundleEntry {
        path: path.to_owned(),
        content: std::fs::read(bundle.join(path)).unwrap_or_default(),
    };
    capsule_identity::encode_entries(&[read("capsule.json"), read("capsule.wasm")])
}
